# ── Upsert helper ─────────────────────────────────────────────────────────────
def upsert_many(collection, docs, key_field):
    """Insert new records; update only changed ones; skip identical ones."""
    inserted = updated = skipped = 0
    for doc in docs:
        filter_q = {key_field: doc.get(key_field)}
        result   = collection.update_one(filter_q, {"$set": doc}, upsert=True)
        if result.upserted_id:      inserted += 1
        elif result.modified_count: updated  += 1
        else:                       skipped  += 1
    return inserted, updated, skipped

def _report(coll_name, ins, upd, skp):
    print(f"  {coll_name}: {ins} inserted, {upd} updated, {skp} unchanged")

# ── Upsert into production_db_hungary collections ────────────────────────────
print("Upserting data into collections...")

ins, upd, skp = upsert_many(db["machine_no"],       machine_no,       "machine")
_report("machine_no", ins, upd, skp)

ins, upd, skp = upsert_many(db["curing_press_dict"], curing_press_dict,"curing_press_id")
_report("curing_press_dict", ins, upd, skp)

ins, upd, skp = upsert_many(db["ub_machine_no"],     ub_machine_no,    "ubno")
_report("ub_machine_no", ins, upd, skp)

ins, upd, skp = upsert_many(db["channel_no_ufm"],    channel_no_ufm,   "sku")
_report("channel_no_ufm", ins, upd, skp)

ins, upd, skp = upsert_many(db["channel_no_tbm"],    channel_no_tbm,   "sku")
_report("channel_no_tbm", ins, upd, skp)

ins, upd, skp = upsert_many(db["channel_no_curing"], channel_no_curing,"sku")
_report("channel_no_curing", ins, upd, skp)

ins, upd, skp = upsert_many(db["gyo_qr_status"],     gyo_qr_status,    "sku")
_report("gyo_qr_status", ins, upd, skp)

# re_codes: composite key (condition_code + description)
ri = ru = rs = 0
for doc in re_codes:
    result = db["re_codes"].update_one(
        {"condition_code": doc["condition_code"], "description": doc["description"]},
        {"$set": doc}, upsert=True
    )
    if result.upserted_id:      ri += 1
    elif result.modified_count: ru += 1
    else:                       rs += 1
_report("re_codes", ri, ru, rs)

print("Upsert complete!")


