# Function to process collection data
def process_collection(source_collection, target_collection_name, field_name):
    """Upsert machine docs — insert new ones, preserve existing status/comment."""
    target_collection = manage_skus_db[target_collection_name]
    ins = upd = skp = 0
    for doc in db[source_collection].find():
        field_val = doc.get(field_name)
        result = target_collection.update_one(
            {field_name: field_val},
            {"$setOnInsert": {
                field_name:  field_val,
                "status":    "active",
                "timestamp": current_timestamp,
                "UserID":    1,
                "comment":   []
            }},
            upsert=True
        )
        if result.upserted_id:      ins += 1
        elif result.modified_count: upd += 1
        else:                       skp += 1
    print(f"  {target_collection_name}: {ins} inserted, {upd} updated, {skp} unchanged")

# Process each collection
process_collection("machine_no",       "tbm_machine",    "machine")
process_collection("curing_press_dict","curing_machine", "curing_press_id")
process_collection("ub_machine_no",    "ufm_machine",    "ubno")

# dashboard_cbc.dashboard_workcenter — upsert by machine name
dashboard_collection = dashboard_cbc_db["dashboard_workcenter"]

def _upsert_workcenter(machine_name, source_doc):
    dashboard_collection.update_one(
        {"machine": machine_name},
        {"$setOnInsert": {
            "machine":   machine_name,
            "status":    source_doc.get("status", "active"),
            "timestamp": source_doc.get("timestamp", current_timestamp),
            "UserID":    source_doc.get("UserID", 1),
            "comment":   source_doc.get("comment", [])
        }},
        upsert=True
    )

for doc in manage_skus_db["tbm_machine"].find():
    _upsert_workcenter(doc["machine"], doc)

for doc in manage_skus_db["curing_machine"].find():
    _upsert_workcenter(doc["curing_press_id"], doc)

for doc in manage_skus_db["ufm_machine"].find():
    _upsert_workcenter(doc["ubno"], doc)

print("dashboard_workcenter upserted (new machines inserted, existing preserved).")
print("All collections processed successfully.")

